	"os"
	"strconv"
	"strings"
)

func triangleNumbers(x int) int {
	return x * (x + 1) / 2
}

func maxTrianglePossible(n int) int {
	// Solve k(k+1)/2 <= n -> k^2 + k - 2n <= 0
	// k = floor((-1 + sqrt(1 + 8n)) / 2)
	if n <= 0 {
		return 0
	}
	return int((math.Sqrt(float64(1+8*n)) - 1) / 2)
}

func funkyNumbers(n int) string {
	funkyNumber := "NO"
	maxTriangle := maxTrianglePossible(n)

	for i := maxTriangle; i > 0; i-- {
		firstTriangle := triangleNumbers(i)
		rem := n - firstTriangle

		if rem == 0 {
			continue
		}

		secFactor := maxTrianglePossible(rem)
		secTriangle := triangleNumbers(secFactor)

		triangles := firstTriangle + secTriangle

		if triangles == n {
			funkyNumber = "YES"
			break
		}
	}

	return funkyNumber
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	input, _ := reader.ReadString('\n')
	input = strings.TrimSpace(input)

	n, _ := strconv.Atoi(input)

	res := funkyNumbers(n)
	fmt.Println(res)
}

